---RefreshUI
---@param oneMatchChartData table leftPlayerId leftInfo rightPlayerId rightInfo positionWheel matchResultIndex inBattle
---@param playerId          number  玩家id
---@param isCanQuiz         boolean 是否能投票
function PVPArenaAgainstHeadDoubleNode:RefreshUI(oneMatchChartData, playerId, isCanQuiz)
    local leftPlayerId     = oneMatchChartData.leftPlayerId
    local leftScore        = oneMatchChartData.leftScore
    local rightPlayerId    = oneMatchChartData.rightPlayerId
    local rightScore       = oneMatchChartData.rightScore
    local inBattle         = oneMatchChartData.inBattle

    local pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    local battleStatus      = checkNumber(pvpArenaEntryDojo.battleStatus)
    local mainPanelStatus   = pvpArenaComponent:GetMainPanelStatus()

    local t = {
        [leftPlayerId]  = Direction.Left,
        [rightPlayerId] = Direction.Right,
    }
    --print(leftPlayerId, rightPlayerId, playerId, "------------>>>>>")
    local direction         = t[playerId]
    local isPlayerSelf      = direction ~= nil
    local state             = PVPArenaUtils.InitMatchChartClickState(self.isAudience, isPlayerSelf, battleStatus, mainPanelStatus)
    --self.state              = state
    self.direction          = direction
    self.oneMatchChartData  = oneMatchChartData
    self.isCanQuiz          = isCanQuiz
    self.playerId           = playerId

    local isLeftLoser, isRightLoser = false, false
    if leftScore and rightScore then
        isLeftLoser = checkNumber(leftScore) < checkNumber(rightScore)
        isRightLoser = checkNumber(rightScore) < checkNumber(leftScore)
    end

    local quizzedMap = pvpArenaComponent:GetQuizzedMap()
    local leftIsQuizzed = quizzedMap[tostring(leftPlayerId)] ~= nil
    self:RefreshHeadGroupNode(self.HeadGroup1.gameObject, oneMatchChartData.leftInfo, leftPlayerId, isLeftLoser, leftIsQuizzed)
    local rightIsQuizzed = quizzedMap[tostring(rightPlayerId)] ~= nil
    self:RefreshHeadGroupNode(self.HeadGroup2.gameObject, oneMatchChartData.rightInfo, rightPlayerId, isRightLoser, rightIsQuizzed)

    KTool.SetActive(self.InBattleGroup.gameObject, inBattle)

    --- 是否左右两侧玩家都投过票
    local isQuizzed = leftIsQuizzed and rightIsQuizzed
    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    --- 战斗状态为等待开始 并且 能显示编队界面
    local isShowEditTeamBtn = seasonFlag > PVPArenaSeasonFullStatus.Closed and seasonFlag <= PVPArenaSeasonFullStatus.Group and self.battleRound == 0 and battleStatus ~= PVPArenaBattleStatus.InBattle and state == PVPArenaHeadNodeClickState.ShowFormationDialog
    local isShowBtn = (isCanQuiz and not isQuizzed) or isShowEditTeamBtn
    KTool.SetActive(self.Button.gameObject, isShowBtn)
    if isShowBtn then
        if self.isFirstRegButtonAction then
            UIEventProxy.Create(self.Button.gameObject).onPointerClick = Bind(self, self.OnClickButtonAction)
            self.isFirstRegButtonAction = nil
        end
        self:RefreshButtonText(isCanQuiz, isShowEditTeamBtn)
    end

    --return isPlayerSelf
end

---RefreshHeadGroupNode
---@param gameObject UnityEngine.GameObject
---@param info table
---@param isPlayerSelf boolean
function PVPArenaAgainstHeadDoubleNode:RefreshHeadGroupNode(gameObject, info, playerId, isLoser, isQuizzed)
    ---@type PVPArenaAgainstHeadGroupNode
    local env = CfUtils.GetLuaScr(gameObject, PVPArenaAgainstHeadGroupNodePath)
    if isNull(env) then return end
    local isShowTicketNum = pvpArenaComponent:GetMainPanelStatus() == Constants.PVPArenaMainPanelStatus.Notice
    env:SetOneMatchChartData(self.oneMatchChartData)
    --env:SetState(self.state)
    env:SetSelfPlayerId(self.playerId)
    env:RefreshUI(info, playerId, isShowTicketNum, isLoser, isQuizzed)
end

function PVPArenaAgainstHeadDoubleNode:RefreshButtonText(isCanQuiz, isShowEditTeamBtn)
    local buttonText
    if isCanQuiz then
        buttonText = localize("推选")
    elseif isShowEditTeamBtn then
        buttonText = localize("编辑")
    end
    self.ButtonText.text = buttonText
end

