function PVPArenaAgainstHeadDoubleNode:OnClickButtonAction()
    local excludeDialogs = {
        {id = Constants.UITypeIds.PVPArenaAgainstDialog}
    }
    local oneMatchChartData = self.oneMatchChartData
    local leftPlayerId      = oneMatchChartData.leftPlayerId
    local rightPlayerId     = oneMatchChartData.rightPlayerId
    local isPlayerSelf      = leftPlayerId == self.playerId or rightPlayerId== self.playerId
    local battleStatus      = checkNumber(pvpArenaComponent:GetPVPArenaEntryDojo().battleStatus)
    local mainPanelStatus   = pvpArenaComponent:GetMainPanelStatus()
    local state             = PVPArenaUtils.InitMatchChartClickState(self.isAudience, isPlayerSelf, battleStatus, mainPanelStatus)
    --- 按钮不会进入比赛信息
    PVPArenaUtils.ShowDialogByMatchChartState(state, self.oneMatchChartData, nil, excludeDialogs)
end

